$formFields=static function(array $defaults=[]): void { foreach(['razao_social'=>'Razão social','nome_fantasia'=>'Nome fantasia','documento'=>'CPF/CNPJ','segmento'=>'Segmento','contato'=>'Contato responsável','telefone'=>'Telefone','email'=>'E-mail','inscricao_estadual'=>'Inscrição estadual','inscricao_municipal'=>'Inscrição municipal','endereco_logradouro'=>'Logradouro','endereco_numero'=>'Número','endereco_complemento'=>'Complemento','endereco_bairro'=>'Bairro','endereco_cidade'=>'Cidade','endereco_uf'=>'UF','endereco_cep'=>'CEP'] as $key=>$label){echo '<div class="form-group"><label class="form-label">'.h($label).'</label><input class="form-control-os" name="'.$key.'" maxlength="150" value="'.h($defaults[$key]??'').'"></div>';} echo '<div class="form-group"><label class="form-label">Tipo de pessoa</label><select class="form-control-os" name="tipo_pessoa"><option value="juridica">Jurídica</option><option value="fisica">Física</option></select></div><div class="form-group"><label class="form-label">Status</label><select class="form-control-os" name="status"><option value="pendente">Pendente</option><option value="ativo">Ativa</option><option value="inativo">Inativa</option><option value="bloqueado">Bloqueada</option></select></div><div class="form-group"><label class="form-label">Usuário responsável (ID, opcional)</label><input class="form-control-os" inputmode="numeric" name="responsavel_usuario_id"></div>';};
?>
