['id'])?>"><button class="dropdown-item"><i class="bi bi-box-arrow-in-right"></i> Entrar na empresa</button></form></li><li><hr class="dropdown-divider"></li><?php foreach(['ativo'=>'Ativar','inativo'=>'Inativar','bloqueado'=>'Bloquear'] as $status=>$label):?><li><form method="post" action="actions/admin-empresa-status.php"><?= $csrf->field() ?><input type="hidden" name="empresa_id" value="<?=h($company['id'])?>"><input type="hidden" name="status" value="<?=$status?>"><button class="dropdown-item <?= $status==='bloqueado'?'text-danger':'' ?>"><?=$label?></button></form></li><?php endforeach;?></ul></div></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
