ld() ?><input type="hidden" name="fornecedor_so_id" value="<?=h($supplier->id())?>"><p>Fornecedor: <strong><?=h($supplier->name())?></strong></p><div class="form-row-3"><?php $formFields(['razao_social'=>$supplier->name(),'nome_fantasia'=>$supplier->name(),'documento'=>$supplier->cnpj()??'','contato'=>$supplier->contact()??'','telefone'=>$supplier->phone()??'']);?></div></div><div class="modal-footer"><button class="btn-modal-save">Confirmar cadastro</button></div></form></div></div><?php endforeach;?><?php endif;?></section><?php endif;?></div>
